import { z } from 'zod';

const User = z.object({ id: z.number(), name: z.string() });

const getUser = stitch<{ id: number; name: string }>({
    baseUrl: 'https://api.example.com',
    path: '/users/{id}',
    output: User,
});
```

The `output` schema runs against each response; pairing it with the
`stitch<{ id: number; name: string }>` generic types the validated result.

538.text:
```ts twoslash
import { stitch } from 'stitchapi';
import { z } from 'zod';

const createUser = stitch<{ id: number; name: string }>({
    method: 'POST',
    baseUrl: 'https://api.example.com',
    path: '/users',
    input: { body: z.object({ name: z.string() }) },
    output: z.object({ id: z.number(), name: z.string() }),
});
```

A bad `body` rejects before the POST is sent; a response that doesn't match
`output` rejects after. Either way the stitch throws
[STITCH\_VALIDATION](/docs/errors/stitch-validation), and the `stitch<T>` generic
keeps the resolved value typed as `{ id: number; name: string }`.

542.text:
```ts twoslash
import { stitch } from 'stitchapi';

const lookup = stitch<{ id: string } | { missing: true }>({
    baseUrl: 'https://api.example.com',
    path: '/items/{id}',
    acceptStatus: [404], // a 404 is "not found", not a thrown error
    transform: (body) =>
        // Reshape the 404 payload into a sentinel your code can branch on.
        body && typeof body === 'object' && 'id' in body
            ? body
            : { missing: true },
});

const item = await lookup({ params: { id: 'abc' } });
if ('missing' in item) {
    // fall back to a broader call — no try/catch needed
}
```

A `404` here **resolves** with the response body instead of rejecting. Everything
else (`401`, `500`, …) still throws a `StitchError` exactly as before — `acceptStatus`
is additive, never a blanket "ignore failures".

543.text:
`acceptStatus` is either a number list or a predicate `(status) => boolean`. Use a
predicate to accept a range:

```ts twoslash
