    url: 'https://api.example.com/users/{id}',
    hooks: {
        onRequest: ({ name, attempt, req }) => {
            console.log(`→ ${name} #${attempt}: ${req?.method} ${req?.url}`);
        },
        onResponse: ({ res }) => {
            console.log(`← ${res?.status}`);
        },
        onRetry: ({ attempt, error, res }) => {
            console.log(`retrying after #${attempt}`, error ?? res?.status);
        },
    },
});
```

```ts twoslash
import { stitch } from 'stitchapi';

const getUser = stitch<{ id: number; name: string }>({
    baseUrl: 'https://api.example.com',
    path: '/users/{id}',
    unwrap: 'data.user',
});

// `user` is the inner { id, name } object, not the { data: { user } } envelope.
const user = await getUser({ params: { id: 1 } });
```

```ts twoslash
import { stitch } from 'stitchapi';

const getUser = stitch<{ id: number; name: string }>({
    baseUrl: 'https://api.example.com',
    path: '/users/{id}',
});

// Await it for just the value…
const user = await getUser({ params: { id: 1 } });

// …or iterate the typed event stream for everything that happened.
for await (const event of getUser.stream({ params: { id: 1 } })) {
    if (event.type === 'result') console.log(event.data);
}
```

```ts twoslash
import { stitch } from 'stitchapi';

const listing = stitch({
    baseUrl: 'https://api.example.com',
    path: '/listings',
    // The body is `unknown` — narrow it, then reshape the raw envelope into a
    // plain array before unwrap and validation run.
    transform: (body) => (body as { results: unknown[] }).results,
});
```

The raw body arrives as a wrapped `{ results: [...] }`; `transform` returns the
inner array, and everything downstream works against that array instead.

```ts twoslash
import { stitch } from 'stitchapi';

const lookup = stitch<{ id: string } | { missing: true }>({
    baseUrl: 'https://api.example.com',
    path: '/items/{id}',
    acceptStatus: [404], // a 404 is "not found", not a thrown error
    transform: (body) =>
        // Reshape the 404 payload into a sentinel your code can branch on.
        body && typeof body === 'object' && 'id' in body
            ? body
            : { missing: true },
});

const item = await lookup({ params: { id: 'abc' } });
if ('missing' in item) {
    // fall back to a broader call — no try/catch needed
}
```

A `404` here **resolves** with the response body instead of rejecting. Everything
else (`401`, `500`, …) still throws a `StitchError` exactly as before — `acceptStatus`
is additive, never a blanket "ignore failures".

```ts twoslash
import { stitch } from 'stitchapi';

const orders = stitch({
    baseUrl: 'https://api.example.com',
    path: '/orders',
    circuit: { failures: 5, cooldown: 30_000 },
});
```

After 5 consecutive failures the breaker opens; for the next 30 seconds calls
to `orders()` fast-fail instead of hitting `api.example.com`.

```ts twoslash
import { stitch } from 'stitchapi';

const report = stitch({
    baseUrl: 'https://api.example.com',
    path: '/report',
    timeout: { total: '10s', perAttempt: '3s' },
});
```

Each call to `report()` gives every attempt at most 3 seconds and the whole call
at most 10 seconds; whichever fires first aborts the request.

```ts twoslash
import { stitch } from 'stitchapi';

const search = stitch('https://api.example.com/search');

// Pre-bind a query param; per-call input merges over it.
const inEurope = search.with({ query: { region: 'eu' } });

await inEurope({ query: { q: 'mango' } }); // → region=eu&q=mango
```

`inEurope` shares one runtime with `search`, so a throttle budget or a captured
cookie set is the same whichever you call.

```ts twoslash
import { stitch } from 'stitchapi';

const search = stitch({
    baseUrl: 'https://api.example.com',
    path: '/search',
    throttle: { rate: '5/s', concurrency: 2, scope: 'host' },
});
```

Calls to `search()` are spaced to five per second with at most two running
concurrently. When a call has to wait, the stitch emits a `progress` event with
phase `throttled`, so a waiting call is visible on the event stream rather than
silently stalled.

```ts twoslash
import { stitch } from 'stitchapi';

const submit = stitch({
    method: 'POST',
    baseUrl: 'https://api.example.com',
    path: '/submit',
    bodyType: 'form',
});

await submit({ body: { name: 'mango', qty: 3 } });
```

The body travels in the call input, not the config: `submit` encodes
`{ name: 'mango', qty: 3 }` as an `application/x-www-form-urlencoded` body
because `bodyType` is `'form'`.

```ts twoslash
import { stitch } from 'stitchapi';
import { z } from 'zod';

const createUser = stitch<{ id: number; name: string }>({
    method: 'POST',
    baseUrl: 'https://api.example.com',
    path: '/users',
    input: { body: z.object({ name: z.string() }) },
    output: z.object({ id: z.number(), name: z.string() }),
});
```

A bad `body` rejects before the POST is sent; a response that doesn't match
`output` rejects after. Either way the stitch throws
[STITCH\_VALIDATION](/docs/errors/stitch-validation), and the `stitch<T>` generic
keeps the resolved value typed as `{ id: number; name: string }`.

```ts twoslash
import { stitch } from 'stitchapi';
import { z } from 'zod';

const User = z.object({ id: z.number(), name: z.string() });

const getUser = stitch<{ id: number; name: string }>({
    baseUrl: 'https://api.example.com',
    path: '/users/{id}',
    output: User,
});
```

The `output` schema runs against each response; pairing it with the
`stitch<{ id: number; name: string }>` generic types the validated result.

```ts twoslash
import { stitch } from 'stitchapi';
import type { StitchStore } from 'stitchapi';

// A shared store — e.g. @stitchapi/redis's redisStore() — see The pluggable store.
declare const sharedStore: StitchStore;

const search = stitch({
    baseUrl: 'https://api.example.com',
    path: '/search',
    throttle: { rate: '10/s', scope: 'host' },
    store: sharedStore, // the budget now spans all workers using this store
});
```

```ts twoslash
import { stitch } from 'stitchapi';
import type { StitchStore } from 'stitchapi';

// A StitchStore is just three async methods + TTL — back it with anything.
const sharedStore: StitchStore = {
    async get(key) {
        /* read from your shared backend */
        return undefined;
    },
    async set(key, value, ttl) {
        /* write, honoring ttl */
    },
    async incr(key, ttl) {
        /* atomic counter with a TTL window */
        return 1;
    },
};

const getUser = stitch({
    baseUrl: 'https://api.example.com',
    path: '/users/{id}',
    store: sharedStore,
});
```

